const CSS_FILES = {"simple.css":"/* Simplified system. Sizes: 44 / 18 / 16 (button only) / 15 / 13.\n   Weights 400 / 500. Line height 1.2 (scanned) / 1.6 (read). No letter-spacing.\n   Colors: header #111 + #4a4a4a, body #f7f7f7 + #a3a3a3, lines #d5d5d5 / #333. */\n@font-face { font-family: Inter; font-weight: 100 900; src: url('{{FONT}}') format('woff2'); }\n* { margin: 0; padding: 0; box-sizing: border-box; letter-spacing: normal; }\nbody { font-family: Inter, system-ui, sans-serif; font-optical-sizing: auto; color: #111; -webkit-font-smoothing: antialiased; }\nb, strong { font-weight: 500; }\n.page { width: 816px; height: 1056px; display: flex; flex-direction: column; overflow: hidden; }\n\n/* header */\n.header { background: #f7f7f7; border-bottom: 1px solid #d5d5d5; }\n.topbar { display: flex; justify-content: space-between; align-items: center; padding: 16px 48px; border-bottom: 1px solid #d5d5d5; font-size: 13px; line-height: 1.2; }\n.brand { display: flex; align-items: center; gap: 10px; font-weight: 500; }\n.avatar { width: 24px; height: 24px; border-radius: 50%; }\n.qtitle { padding: 32px 48px; }\n.headline { font-size: 44px; font-weight: 500; line-height: 1.2; }\n.subhead { font-size: 18px; line-height: 1.6; color: #4a4a4a; margin-top: 8px; }\n.header .muted { color: #4a4a4a; }\n\n/* body */\n.body { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: 32px 48px 28px; background: #111; color: #f7f7f7; }\n.muted { color: #a3a3a3; }\n.footer { display: flex; justify-content: space-between; margin-top: auto; border-top: 1px solid #333; padding-top: 14px; font-size: 13px; line-height: 1.6; color: #a3a3a3; }\n.sec { border-top: 1px solid #333; padding-top: 20px; margin-top: 20px; }\n.sec.first { border-top: 0; padding-top: 0; margin-top: 0; }\n.big { display: block; font-size: 44px; font-weight: 500; line-height: 1.2; margin-top: 6px; }\n.h { display: block; font-size: 18px; font-weight: 500; line-height: 1.2; }\n.h15 { display: block; font-size: 15px; font-weight: 500; line-height: 1.2; }\n.text { font-size: 15px; line-height: 1.6; color: #a3a3a3; margin-top: 6px; }\n.text b { color: inherit; }\n.small { display: block; font-size: 13px; font-weight: 500; line-height: 1.2; }\n.block { font-weight: 400; line-height: 1.6; margin-top: 4px; }\n.center { text-align: center; margin-top: 10px; }\n\n/* p1 top: grid + flat profile column */\n.top { display: flex; gap: 24px; }\n.top .main { flex: 1; min-width: 0; }\n.aside { width: 236px; flex-shrink: 0; border-left: 1px solid #333; padding-left: 24px; }\n.prow { display: flex; justify-content: space-between; gap: 8px; padding: 12px 0; border-top: 1px solid #333; font-size: 15px; line-height: 1.2; }\n.prow:first-child { border-top: 0; padding-top: 0; }\n.bf-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n.bf-item { text-align: center; }\n.bf-img { display: block; aspect-ratio: 1/1; border: 1px solid #333; border-radius: 8px; overflow: hidden; }\n.bf-img img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.bf-item.selected .bf-img { outline: 1px solid #f7f7f7; outline-offset: -1px; }\n.bf-label { display: block; margin-top: 8px; font-size: 13px; font-weight: 500; line-height: 1.2; color: #a3a3a3; }\n.bf-item.selected .bf-label { color: #f7f7f7; }\n\n/* ORIGINAL FFMI scale: same gradient, range, labels, box and arrow.\n   Only its text follows the type scale (13px ticks, labels 400/500 instead of 700). */\n.ffmi-scale { position: relative; margin-top: 26px; }\n.ffmi-scale-track { position: relative; }\n.ffmi-scale-bar { display: flex; height: 30px; border-radius: 7px; overflow: hidden;\n  background: linear-gradient(to right, #ea3323 0%, #f5be41 14.3%, #7ecc47 28.6%, #4ea667 42.9%, #5093a7 57.1%, #606ae5 71.4%, #6a38cb 85.7%, #4a49cc 100%); }\n.ffmi-scale-bar span { flex: 1; display: flex; align-items: center; justify-content: center; text-align: center; font-size: 13px; font-weight: 500; color: #fff; line-height: 1.2; white-space: nowrap; }\n.ffmi-scale-ticks { display: flex; justify-content: space-between; margin-top: 8px; font-size: 13px; line-height: 1.2; color: #a3a3a3; }\n.ffmi-range-box { position: absolute; top: -5px; bottom: -5px; border: 2px solid #fff; border-radius: 8px; }\n.ffmi-range-arrow { position: absolute; top: -20px; transform: translateX(-50%); font-size: 13px; line-height: 1; color: #fff; }\n\n/* p2 */\n.pics { display: flex; gap: 12px; }\n.pic { position: relative; flex: 1; height: 250px; border: 1px solid #333; border-radius: 8px; overflow: hidden; display: flex; justify-content: center; }\n.pic img { height: 100%; }\n.chip { position: absolute; top: 10px; left: 10px; padding: 4px 8px; border-radius: 4px; background: #f7f7f7; color: #111; font-size: 13px; font-weight: 500; line-height: 1.2; }\n.pics + .sec { margin-top: 24px; }\n.track { position: relative; height: 8px; background: #333; border-radius: 999px; margin: 20px 0 8px; }\n.track-span { position: absolute; top: 0; height: 100%; background: #f7f7f7; border-radius: 999px; }\n.track-dot { position: absolute; top: 50%; width: 14px; height: 14px; border-radius: 50%; background: #a3a3a3; border: 3px solid #111; transform: translate(-50%, -50%); }\n.track-ends { display: flex; justify-content: space-between; font-size: 13px; line-height: 1.2; color: #a3a3a3; }\n.legend { display: flex; justify-content: center; gap: 24px; margin-top: 10px; font-size: 13px; line-height: 1.2; color: #a3a3a3; }\n.legend i { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }\n.dot-today { background: #a3a3a3; } .dot-goal { background: #f7f7f7; }\n\n/* p3 timeline (marker positions unchanged: 22 / 44 / 88%) */\n.timeline { padding: 0 8px; }\n.timeline-track { position: relative; height: 4px; background: #333; border-radius: 999px; margin: 76px 0 10px; }\n.timeline-marker { position: absolute; top: 50%; width: 14px; height: 14px; border-radius: 50%; border: 3px solid #111; transform: translate(-50%, -50%); background: #a3a3a3; }\n.timeline-marker.rec { background: #f7f7f7; }\n.timeline-tag { position: absolute; bottom: 100%; transform: translateX(-50%); margin-bottom: 14px; width: 140px; text-align: center; color: #a3a3a3; display: flex; flex-direction: column; gap: 4px; }\n.timeline-tag.rec { color: #f7f7f7; }\n.timeline-tag .h { font-size: 18px; }\n.timeline-ends { display: flex; justify-content: space-between; }\n.row { display: flex; gap: 20px; padding: 12px 0; border-top: 1px solid #333; }\n.row:first-child { border-top: 0; padding-top: 0; }\n.row .h15 { flex: 0 0 200px; line-height: 1.6; }\n.row .text { margin: 0; }\n\n/* p4 */\n.check { display: flex; gap: 12px; margin-top: 14px; }\n.box { width: 18px; height: 18px; flex-shrink: 0; border: 1px solid #a3a3a3; border-radius: 4px; }\n\n/* p5 */\n.video { display: block; position: relative; border-radius: 8px; overflow: hidden; border: 1px solid #333; }\n.video img { display: block; width: 100%; height: 300px; object-fit: cover; }\n.play { position: absolute; top: 50%; left: 50%; width: 56px; height: 56px; margin: -28px 0 0 -28px; border-radius: 50%; background: #fff; color: #111; display: flex; align-items: center; justify-content: center; }\n.video + .sec { margin-top: 24px; }\n.included { display: flex; flex-direction: column; gap: 10px; margin-top: 14px; }\n.included li { list-style: none; display: flex; gap: 10px; align-items: center; font-size: 15px; line-height: 1.2; }\n.tick { width: 16px; height: 16px; flex-shrink: 0; border-radius: 50%; background: #f7f7f7; color: #111; display: flex; align-items: center; justify-content: center; }\n.cta { display: block; background: #fff; color: #111; text-align: center; font-size: 16px; font-weight: 500; line-height: 1.2; border-radius: 4px; padding: 16px 24px; }\n\n/* ===== all-white \"paper\" version: site palette (#111 text, #4a4a4a muted, #d5d5d5 lines) ===== */\n.header { background: #fff; }\n.body { background: #fff; color: #111; }\n.muted, .text, .bf-label, .ffmi-scale-ticks, .track-ends, .legend, .timeline-tag, .note { color: #4a4a4a; }\n.sec, .aside, .prow, .row, .footer, .bf-img, .pic, .video { border-color: #d5d5d5; }\n.aside .ptop + .prow.prow { border-color: #d5d5d5; }\n.pimg { border-color: #d5d5d5; }\n.bf-item.selected .bf-img { outline-color: #111; }\n.bf-item.selected .bf-label, .timeline-tag.rec { color: #111; }\n.ffmi-range-box { border-color: #111; }\n.ffmi-range-arrow { color: #111; }\n.chip { background: #111; color: #fff; }\n.track, .timeline-track { background: #d5d5d5; }\n.track-span, .timeline-marker.rec, .dot-goal { background: #111; }\n.track-dot, .timeline-marker, .dot-today { background: #4a4a4a; border-color: #fff; }\n.box { border-color: #4a4a4a; }\n.tick { background: #111; color: #fff; }\n.cta { background: #111; color: #fff; }\n\n.pics2 .pic2 { height: 260px; }\n"};
const DARK = "/* dark body: everything below the title */\n.page .body { background: #111; color: #f7f7f7; }\n.page .body .muted, .page .body .text, .page .body .note, .page .body .bf-label, .page .body .ticks, .page .body .trk-ends, .page .body .legend2, .page .body .wbar-ends, .page .body .flegend, .page .body .g6 .bf-label { color: #a3a3a3; }\n.page .body .h, .page .body .h15, .page .body .v44, .page .body .v28, .page .body .idv, .page .body .prow span:last-child, .page .body .g6-item.sel .bf-label { color: #f7f7f7; }\n.page .body * { border-color: #333 !important; }\n.page .body .card { background: transparent; }\n.page .body [style*=\"background:#eee\"], .page .body .card.key, .page .body .pcard.rec, .page .body .vs .me { background: #262626 !important; border-color: #262626 !important; }\n.page .body [style*=\"background:#f7f7f7\"], .page .body .pic2, .page .body .bf-img { background: #1c1c1c !important; }\n.page .body [style*=\"outline:2px solid #4a4a4a\"] { outline-color: #f7f7f7 !important; }\n.page .body .chip2 { background: #f7f7f7; color: #111; }\n.page .body .trk { background: #333; } .page .body .trk-goal { background: #d5d5d5; } .page .body .trk-dot { border-color: #111; }\n.page .body .trk-gap { background: repeating-linear-gradient(90deg, #d5d5d5 0 4px, transparent 4px 8px); }\n.page .body .legend2 i[style*=\"#4a4a4a\"] { background: #d5d5d5 !important; }\n.page .body .box { border-color: #a3a3a3 !important; }\n.page .body .tk { background: #333; } .page .body .tk path { fill: #f7f7f7; }\n.page .body .cta { background: #fff; color: #111; }\n.page .body svg rect[fill=\"#eee\"], .page .body .g-band { fill: #1c1c1c; }\n.page .body svg text[fill=\"#111\"], .page .body .g-lab.rec { fill: #f7f7f7; }\n.page .body svg text[fill=\"#4a4a4a\"], .page .body .g-txt, .page .body .g-lab { fill: #a3a3a3; }\n.page .body .g-grid { stroke: #2a2a2a; }\n.page .body .pcard.off, .page .body .prow.pace.off { color: #777; }\n";
const NORM = "/* Normalization pass (2026-10-31). Loaded last, so it wins over the older per-page styles.\n   Spacing scale: 8 / 12 / 16 / 24 / 40 / 48. Type: 44 value, 18 row/heading, 15 body/item heading, 13 label/note. Line heights 1.2 scanned, 1.6 read. */\n.page .body { padding: 40px 48px !important; }\n.v44, .v44.long { font-size: 44px !important; line-height: 1.2 !important; }\n.card, .pc, .vs > div { padding: 20px !important; }\n.cards { gap: 12px !important; }\n.sec { margin-top: 24px !important; padding-top: 24px !important; }\n.sec.first { margin-top: 0 !important; padding-top: 0 !important; }\n.note { margin-top: 8px !important; }\n.page svg text { font-size: 13px !important; }\n.pr .yv { font-weight: 400 !important; }\n.pr { padding: 16px 0 !important; } .pr:first-child { padding-top: 0 !important; }\n.cta { text-decoration: none !important; }\n/* chart legend: lines, drawn like the chart lines (2px other paces, 4px recommended, slower dashed) */\n.legend2 i.ln { width: 16px; height: 2px; border-radius: 0; vertical-align: 4px; }\n.legend2 i.ln.rec { height: 4px; vertical-align: 3px; }\n.nb { white-space: nowrap; } .pr .r:empty { display: none; }\n";
const BOXES = "/* Box system (2026-11-06): primary #333333, secondary = no fill, 1px #333 border (border adds on top of padding).\n   The enhancer is the 2px ring on the picked body-fat picture (dark.css), unchanged. */\n.page .body .card, .page .body .pc, .page .body .vs > div, .page .body .pic2, .page .body .bf-img { background: transparent !important; border: 1px solid #333 !important; }\n.page .body .card.key, .page .body .card[style*=\"background:#eee\"], .page .body .vs .me { background: #333333 !important; border: 1px solid #333333 !important; }   /* same box size as the outline box */\n.page .body .card:has(.v44.long) { flex: 1.25; }\n.page .body .sec > .h + .prow { margin-top: 8px; }\n";
const SPACING = "/* Spacing system (2026-11-06). Loaded last. Tokens: 8 / 12 / 16 / 24 / 40·48.\n   A. Section: 24 + 1px line + 24.            B. Section heading → content 16, → its own description 8.\n   C. Inside a box or item: each line 8 apart. D. Caption or note under a block 8; paragraph to paragraph 8.\n   E. Block to block in one section 16.       F. Graphic → its axis, ends or legend 8.\n   G. Box padding 20; boxes side by side 12; side-by-side text columns 24; checklist 12 rows / 24 columns; icon to text 8.\n   H. Rows: 12 above and below, line between rows only (none above the first, no padding after the last). */\n\n/* A */\n.page .body .sec { margin-top: 24px !important; padding-top: 24px !important; border-top: 1px solid #333 !important; }\n.page .body .sec.first { margin-top: 0 !important; padding-top: 0 !important; border-top: 0 !important; }\n.page .body .idrow { padding-bottom: 24px !important; margin-bottom: 24px !important; }\n\n/* B */\n.page .body .h { margin: 0 !important; }\n.page .body .h + * { margin-top: 16px !important; }\n.page .body .h + .text { margin-top: 8px !important; }\n\n/* C */\n.page .body .card .small + .v44, .page .body .idrow .idv { margin-top: 8px !important; }\n.page .body .st, .page .body .tri > div { gap: 8px !important; }\n.page .body .tlc { gap: 8px !important; } .page .body .tlc .bar { margin-bottom: 4px !important; }\n.page .body .h15 + .text, .page .body .h15 + .note { margin-top: 8px !important; }\n.page .body .pcol { gap: 8px !important; } .page .body .pcol > * { margin-top: 0 !important; margin-bottom: 0 !important; }\n.page .body .g6 .bf-label { margin-top: 8px !important; }\n\n/* D */\n.page .body .note { margin-top: 8px !important; }\n.page .body .text + .text { margin-top: 8px !important; }\n\n/* E */\n.page .body .note + .gauge, .page .body .note + .checks, .page .body .note + .trk, .page .body .note + .rows4 { margin-top: 16px !important; }\n.page .body .cols2 { margin-top: 16px !important; }\n\n/* F */\n.page .body .ticks, .page .body .trk-ends, .page .body .gends, .page .body .legend2 { margin-top: 8px !important; }\n.page .body .fscale.tall { margin-top: 56px !important; }   /* 16 above the \"You\" tag, which sits 40 above the bar */\n\n/* G */\n.page .body .g6 { gap: 12px !important; }\n.page .body .gtop { gap: 24px !important; }\n.page .body .cols2 { display: grid !important; grid-template-columns: 1fr 1fr; gap: 0 12px !important; }\n.page .body .col2 { width: auto !important; } .page .body .col2:first-child { padding-right: 12px; }\n.page .body .checks { gap: 12px 24px !important; } .page .body .ck { gap: 8px !important; }\n\n/* H */\n.page .body .prow { padding: 12px 0 !important; border-top: 1px solid #333 !important; }\n.page .body .h + .prow, .page .body .rows4 > .prow:first-child, .page .body .gside .prow:first-child, .page .body .col2 .h + .prow { border-top: 0 !important; padding-top: 0 !important; }\n.page .body .prow:last-child { padding-bottom: 0 !important; }\n.page .body .pcol > .note { margin-top: 0 !important; }\n/* page 2 headings above pictures; card sub-lines (shared with page 1) */\n.page .body .cols2.heads { margin-top: 0 !important; } .page .body .cols2.heads + .pics2 { margin-top: 16px !important; }\n.page .body .col2 > .prow:first-child { border-top: 0 !important; padding-top: 0 !important; }\n.page .body .csub { display: block; font-size: 13px; line-height: 1.2; margin-top: 16px !important; color: #a3a3a3; }\n.page .body .card.key .csub, .page .body .card[style*=\"background:#eee\"] .csub { color: #d5d5d5; }\n.page .body .sec > .trk:first-child { margin-top: 0 !important; }\n.page .body .trk-dot { border: 2px solid #111 !important; }   /* ring rule: 2px; cut-out ring in page color */\n/* box hierarchy (2026-11-06, option D): label bright in every box, number biggest, bottom line muted and 16px below the number */\n.page .body .card .small.muted { color: #f7f7f7 !important; }\n.page .body .prow:has(+ .note) { padding-bottom: 0 !important; }\n/* page 3 pace table (2026-11-06): muted labels, white values, like pages 1–2; heading is the only 500 */\n.page .body .prow.pace { font-weight: 400 !important; } .page .body .prow.pace > span:first-child { color: #a3a3a3 !important; } .page .body .prow.pace.rec > span:first-child { color: #f7f7f7 !important; } .page .body .prow.pace.off > span { color: #a3a3a3 !important; }\n.page .body .sec > .note:only-child { margin-top: 0 !important; }\n.page .body .prow + .note.pick, .page .body .rows4 + .note.pick { margin-top: 12px !important; }\n.page .body .sec > .prow.pace:first-child { border-top: 0 !important; padding-top: 0 !important; }\n.page .body .sec > .text:first-child { margin-top: 0 !important; }\n.page .body .text .lead { color: #f7f7f7; }\n.page .body .g2bar > span:first-child { border-radius: 6px 0 0 6px; } .page .body .g2bar > span:last-child { border-radius: 0 6px 6px 0; }\n/* pages 5–8 universal pass (2026-11-06): box label to text gap = 16px; note under the coaching pictures sits one section gap below */\n.page .body .vs .small + .text { margin-top: 16px !important; }\n.page .body .pics2.tall + .text { margin-top: 24px !important; }\n.page .body .srcl .note { margin: 0 0 4px !important; } .page .body .h + .srcl { margin-top: 16px !important; }\n.page .body .checks.one { grid-template-columns: 1fr !important; }\n";
const EXTRA = ".gl{margin:0 0 8px 20px;padding:0;list-style:disc;font-size:15px;line-height:1.6;color:#a3a3a3} .gl li{margin:0} @page{size:816px 1056px;margin:0} *{-webkit-print-color-adjust:exact;print-color-adjust:exact} body{margin:0} .page{break-after:page}.page:last-child{break-after:auto}";
const IMGS = {"bf-14-or-below.webp":"","bf-15-19.webp":"","bf-20-24.webp":"","bf-25-29.webp":"","bf-30-39.webp":"","bf-40plus.webp":""};
const FONT = "";
const ORDER = ['Bv1', 'K2', 'TG1', 'DN4', 'TN4', 'EX4', 'p6'];   // Consider Coaching (E1) off until coaching/ has the new video
const ALT = { '14-or-below': '14% or below', '15-19': '15–19%', '20-24': '20–24%', '25-29': '25–29%', '30-39': '30–39%', '40plus': '40% or more' };

// Run one draft script in memory: fake fs (reads the bundled CSS, captures writes), fake argv/env.
function run(src, lead, env) {
  const files = {};
  const fakeFs = {
    readFileSync: (p) => { const k = pathMod.basename(String(p)); if (CSS_FILES[k] === undefined) throw new Error('roadmap-template: unexpected file read ' + p); return CSS_FILES[k]; },
    writeFileSync: (p, data) => { files[pathMod.basename(String(p))] = String(data); },
  };
  const req = (m) => (m === 'fs' ? fakeFs : m === 'path' ? pathMod : /roadmap-calc$/.test(m) ? calcMod : (() => { throw new Error('roadmap-template: unexpected require ' + m); })());
  const proc = { env: Object.assign({}, env), argv: ['node', 'script', JSON.stringify(lead), 'lead', 'C', 'S1', 'B'] };
  new Function('require', 'process', '__dirname', 'console', src)(req, proc, '/roadmap', { log() {}, warn() {}, error() {} });
  return files;
}

function fillTemplate(_html, lead) {
  const L = {
    first_name: String(lead.first_name || '').trim(), last_name: String(lead.last_name || '').trim(), email: String(lead.email || ''),
    height_ft: Number(lead.height_ft), height_in: Number(lead.height_in), weight_lbs: Number(lead.weight_lbs), bodyfat_range: String(lead.bodyfat_range),
  };
  const files = Object.assign({}, run(SRC_P1, L, { FIX: '1' }), run(SRC_PAGE1, L, { BR: '1', FIX: '1' }));
  const styles = new Set(); const bodies = [];
  for (const k of ORDER) {
    const h = files[k + '-lead.html'];
    if (!h) throw new Error('roadmap-template: page ' + k + ' was not built');
    for (const m of h.matchAll(/<style>([\s\S]*?)<\/style>/g)) styles.add(m[1]);
    bodies.push(h.match(/<body>([\s\S]*)<\/body>/)[1].replace(/<style>[\s\S]*?<\/style>/g, ''));
  }
  const a11y = (h) => h
    .replace(/<img src="([^"]*bf-([^./]+)\.webp)">/g, (_, src, k) => '<img src="' + src + '" alt="Male torso at ' + ALT[k] + ' body fat">')
    .replace(/<svg class="chart"/g, '<svg class="chart" role="img" aria-label="Line chart of your weight over time at each pace"');
  const body = bodies.map((b, i) => a11y(b.replace(/<span>Page \d+<\/span>/, '<span>Page ' + (i + 1) + '</span>'))).join('\n');
  let html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>10% Body Fat Roadmap</title><style>' + [...styles].join('\n') + '\n' + DARK + '\n' + EXTRA + '\n' + NORM + '\n' + BOXES + '\n' + SPACING + '</style></head><body>' + body + '</body></html>';
  // the draft scripts point at files under their ROOT folder; swap in the inlined data (plain string splits, no regex scans)
  const ROOTP = SRC_P1.match(/const ROOT = '([^']+)'/)[1];
  for (const f of Object.keys(IMGS)) html = html.split(ROOTP + '/assets/bodyfat/' + f).join('data:image/webp;base64,' + IMGS[f]);
  html = html.split(ROOTP + '/fonts/inter-latin-variable.woff2').join('data:font/woff2;base64,' + FONT);
  if (/\/Applications\/|file:\/\//.test(html)) throw new Error('roadmap-template: a local file path is left in the page');
  return html;
}

module.exports = { fillTemplate };
